package com.xdownload.mobile;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public class DynamicImbalanceTest{
 @Test public void idleWorkerStealsSlowTailAndOutputIsExact()throws Exception{
  byte[] data=new byte[12*1024*1024];new java.util.Random(742).nextBytes(data);File target=File.createTempFile("x8-imbalance",".part");ServerSocket server=new ServerSocket(0,32,InetAddress.getByName("127.0.0.1"));ExecutorService clients=Executors.newCachedThreadPool();AtomicInteger ranges=new AtomicInteger();AtomicBoolean stopped=new AtomicBoolean();Thread accept=new Thread(()->{while(!stopped.get())try{Socket socket=server.accept();clients.execute(()->{try(Socket c=socket){c.setSoTimeout(5000);BufferedReader reader=new BufferedReader(new InputStreamReader(c.getInputStream()));String first=reader.readLine(),line,range=null;while((line=reader.readLine())!=null&&!line.isEmpty())if(line.toLowerCase(java.util.Locale.ROOT).startsWith("range:"))range=line.substring(6).trim();int a=0,b=data.length-1;boolean partial=range!=null;if(partial){ranges.incrementAndGet();String[] bounds=range.substring(6).split("-");a=Integer.parseInt(bounds[0]);b=Integer.parseInt(bounds[1]);}String headers="HTTP/1.1 "+(partial?"206 Partial Content":"200 OK")+"\r\nContent-Type: application/octet-stream\r\nETag: \"test-v1\"\r\nAccept-Ranges: bytes\r\nContent-Length: "+(b-a+1)+"\r\nConnection: close\r\n"+(partial?"Content-Range: bytes "+a+"-"+b+"/"+data.length+"\r\n":"")+"\r\n";OutputStream out=c.getOutputStream();out.write(headers.getBytes(java.nio.charset.StandardCharsets.US_ASCII));out.flush();if(first!=null&&first.startsWith("GET"))for(int i=a;i<=b;i+=65536){if(a==0)Thread.sleep(15);out.write(data,i,Math.min(65536,b-i+1));out.flush();}}catch(Exception ignored){}});}catch(IOException ignored){}});accept.start();
  try{String url="http://127.0.0.1:"+server.getLocalPort()+"/data";AtomicReference<int[]> last=new AtomicReference<>();HttpEngine.Observer obs=new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long d,long t,String e,String m){}public void segments(int[] c){last.set(c);}};assertEquals(data.length,ParallelEngine.transfer(url,true,target,obs,2,true));assertTrue("An idle worker must split the slow remaining tail",ranges.get()>2);assertArrayEquals(data,Files.readAllBytes(target.toPath()));assertNotNull(last.get());for(int n:last.get())assertEquals(1000,n);}finally{stopped.set(true);server.close();accept.join(2000);clients.shutdownNow();clients.awaitTermination(5,TimeUnit.SECONDS);target.delete();ParallelEngine.clear(target);}
 }
}